@Bean
public ApplicationRunner sendMessage(KafkaTemplate<String, String> template) {
    return args -> {
        for (int i = 1; i <= 100; i++) {
            String speed = String.valueOf(Math.round(Math.random() * 1000));
            String brk = String.valueOf(Math.round(Math.random() * 100));
            template.send("InfyRail_C_To_D", "Speed", speed);
            template.send("InfyRail_C_To_D", "BrakeEfficiency", brk);
            Thread.sleep(2000);
        }
    };
}

KStream<String, String> trainData = streamsBuilder.stream("InfyRail_C_To_D");
KTable<String, Long> trainDatum = trainData
    .filter((k, v) -> k.equalsIgnoreCase("BrakeEfficiency"))
    .filter((k, v) -> Long.parseLong(v) < 70)
    .groupBy((k, v) -> v)
    .count(Materialized.as("breakdata"));

trainDatum.toStream().to("InfyRail_C_To_D_Brake_Warning");

