@RestController
@RequestMapping("/breakdata")
public class BreakDataController {
    @Autowired
    StreamsBuilderFactoryBean factoryBean;

    @GetMapping("/{input}")
    public Long getData(@PathVariable("input") String inputpercent) {
        KafkaStreams kafkaStreams = factoryBean.getKafkaStreams();
        ReadOnlyKeyValueStore<String, Long> store =
            kafkaStreams.store(StoreQueryParameters.fromNameAndType("breakdata", QueryableStoreTypes.keyValueStore()));
        return store.get(inputpercent);
    }
}

